ALTER POLICY blockers_read ON public.task_approval_blockers USING(blocker_can_manage(client_id,pipeline_id) OR (has_role(auth.uid(),'client') AND first_reminder_at IS NOT NULL AND EXISTS(SELECT 1 FROM clients c WHERE c.id=client_id AND my_client_id() IN(c.id,c.parent_client_id))));
CREATE OR REPLACE FUNCTION public.complete_activation_followup(_id uuid,_scope text,_onboarded boolean,_assigned boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r pipeline_activation_requests;BEGIN PERFORM activity_require_ready();IF NOT(is_manager(auth.uid()) OR has_role(auth.uid(),'bd_manager')) THEN RAISE EXCEPTION 'BD or management only';END IF;SELECT * INTO r FROM pipeline_activation_requests WHERE id=_id FOR UPDATE;IF r.id IS NULL OR r.status IN('activated','declined') THEN RAISE EXCEPTION 'This request is already closed';END IF;IF coalesce(btrim(_scope),'')='' THEN RAISE EXCEPTION 'Describe the confirmed add-on scope';END IF;IF _assigned AND NOT (_onboarded OR r.onboarding_completed_at IS NOT NULL) THEN RAISE EXCEPTION 'Complete add-on onboarding before assigning pipeline tasks';END IF;UPDATE pipeline_activation_requests SET scope_notes=btrim(_scope),scope_confirmed_at=coalesce(scope_confirmed_at,now()),onboarding_completed_at=CASE WHEN _onboarded THEN coalesce(onboarding_completed_at,now()) ELSE onboarding_completed_at END,tasks_assigned_at=CASE WHEN _assigned THEN coalesce(tasks_assigned_at,now()) ELSE tasks_assigned_at END,status=CASE WHEN (_onboarded OR onboarding_completed_at IS NOT NULL) AND (_assigned OR tasks_assigned_at IS NOT NULL) THEN 'activated' ELSE 'contacted' END WHERE id=_id;END $$;
DO $$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.resolve_approval_blocker(uuid,text)'::regprocedure) INTO f;f:=replace(f,'UPDATE task_approval_blockers SET resolved_at=now()', 'IF b.task_kind=''recurring'' THEN UPDATE recurring_tasks SET status=''done'',done_at=coalesce(done_at,now()),done_by=auth.uid() WHERE id=b.task_id AND stage=''approval'' AND status IN(''blocked'',''waiting_client''); END IF; UPDATE task_approval_blockers SET resolved_at=now()');EXECUTE f;END $$;
CREATE OR REPLACE FUNCTION public.pipeline_member_backup(_pipeline uuid,_person uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT pm.backup_id FROM pipeline_members pm WHERE pm.pipeline_id=_pipeline AND pm.user_id=_person AND pm.active ORDER BY pm.created_at LIMIT 1),pipeline_default_backup(_pipeline)) $$;
REVOKE ALL ON FUNCTION public.pipeline_member_backup(uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.pipeline_member_backup(uuid,uuid) TO authenticated,service_role;
DO $$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.task_blocker_track()'::regprocedure) INTO f;f:=replace(f,'NEW.backup_id:=pipeline_default_backup(pid);','NEW.backup_id:=pipeline_member_backup(pid,CASE WHEN kind=''launch'' THEN NEW.assignee_id ELSE NEW.owner_id END);');
-- Separate branches prevent referencing row fields absent on the other task kind.
f:=replace(f,'NEW.backup_id:=pipeline_member_backup(pid,CASE WHEN kind=''launch'' THEN NEW.assignee_id ELSE NEW.owner_id END);','IF kind=''launch'' THEN NEW.backup_id:=pipeline_member_backup(pid,NEW.assignee_id);ELSE NEW.backup_id:=pipeline_member_backup(pid,NEW.owner_id);END IF;');EXECUTE f;
SELECT pg_get_functiondef('public.activity_backup_guard()'::regprocedure) INTO f;f:=replace(f,'NEW.backup_id:=pipeline_default_backup(pid);','NEW.backup_id:=pipeline_member_backup(pid,NEW.owner_id);');EXECUTE f;
SELECT pg_get_functiondef('public.save_activity_plan(uuid,date,jsonb,uuid,boolean)'::regprocedure) INTO f;f:=replace(f,'pipeline_default_backup(cp.pipeline_id)','pipeline_member_backup(cp.pipeline_id,own)');EXECUTE f;END $$;